// Parse the feed body, dedupe against the regulatory_items table.
// Returns one item per new entry.
const Parser = require('rss-parser');
const parser = new Parser({ timeout: 10000 });

const feedMeta = $('List Feeds').item.json;
const body = $input.first().json.body || '';

let feed;
try {
  feed = await parser.parseString(body);
} catch (e) {
  return [{ json: { feed_id: feedMeta.feed_id, status: 'parse_error', error: e.message } }];
}

// For each item, return a flat record. Dedupe happens against the DB in the next node.
const items = (feed.items || []).map(item => ({
  json: {
    feed_id: feedMeta.feed_id,
    item_guid: item.guid || item.link || item.title,
    title: item.title || '',
    link: item.link || '',
    summary: (item.contentSnippet || item.content || '').slice(0, 4000),
    published_at: item.isoDate || item.pubDate || new Date().toISOString(),
  }
}));

return items;

