// Parse classification, decide alert vs digest, write to DB.
const llm = $input.first().json;
const item = $('Parse + Map Items').item.json;
const text = llm.content?.[0]?.text || '';

let cls;
try {
  cls = JSON.parse(text.match(/\{[\s\S]*\}/)[0]);
} catch (e) {
  cls = { relevant_to_profile: false, urgency: 'low', summary: 'Classification failed: ' + e.message, jurisdictions_implicated: [], regulatory_areas: [], recommended_owner: 'unknown' };
}

const alertNow = !!cls.relevant_to_profile && cls.urgency === 'high';

return [{
  json: {
    feed_id: item.feed_id,
    item_guid: item.item_guid,
    title: item.title,
    link: item.link,
    summary_raw: item.summary,
    summary_classified: cls.summary,
    published_at: item.published_at,
    relevant_to_profile: !!cls.relevant_to_profile,
    jurisdictions: cls.jurisdictions_implicated || [],
    regulatory_areas: cls.regulatory_areas || [],
    urgency: cls.urgency || 'low',
    recommended_owner: cls.recommended_owner || 'unknown',
    alert_now: alertNow,
    classified_at: new Date().toISOString(),
  }
}];

